class Solution {
    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.length;
        int n = students[0].length;

        // Precompute compatibility scores between every student and mentor
        int[][] score = new int[m][m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int comp = 0;
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) {
                        comp++;
                    }
                }
                score[i][j] = comp;
            }
        }

        // Use bitmask dp to assign mentors to students
        // dp[mask] = max compatibility sum for assigned mentors in mask
        int[] dp = new int[1 << m];

        for (int mask = 0; mask < (1 << m); mask++) {
            int studentIndex = Integer.bitCount(mask);
            if (studentIndex == m) continue; // all assigned

            for (int mentor = 0; mentor < m; mentor++) {
                if ((mask & (1 << mentor)) == 0) {
                    int nextMask = mask | (1 << mentor);
                    dp[nextMask] = Math.max(dp[nextMask], dp[mask] + score[studentIndex][mentor]);
                }
            }
        }

        return dp[(1 << m) - 1];
    }
}

